export const budgets = defineTable(
  'budgets',
  { module: 'M24', scope: 'org' },
  {
    ...baseColumns,
    fiscalYearId: uuid()
      .references((): AnyPgColumn => fiscalYears.id)
      .notNull(),
    /** empty for a group-level budget */
    branchId: uuid().references((): AnyPgColumn => branches.id),
    name: text().notNull(),
    status: enumText(budgetStatuses).notNull().default('draft'),
    approvalRequestId: uuid().references((): AnyPgColumn => approvalRequests.id),
    checkMode: enumText(budgetCheckModes).notNull().default('warn'),
  },
  (t) => [
    uniqueIndex('budgets_fiscal_year_branch_uq')
      .on(
        t.fiscalYearId,
        sql`coalesce(${t.branchId}, '00000000-0000-0000-0000-000000000000'::uuid)`,
      )
      .where(sql`${t.deletedAt} is null and ${t.status} = 'approved'`),
  ],
);

export const budgetLines = defineTable(
  'budget_lines',
  { module: 'M24', scope: 'org' },
  {
    ...baseColumns,
    budgetId: uuid()
      .references((): AnyPgColumn => budgets.id)
      .notNull(),
    /** an income or expense account */
    accountId: uuid()
      .references((): AnyPgColumn => accounts.id)
      .notNull(),
    costCenterId: uuid().references((): AnyPgColumn => costCenters.id),
    /** twelve amounts, one per fiscal period */
    monthly: paisa().array().notNull(),
    /** generated: the sum of `monthly` */
    annual: paisa().generatedAlwaysAs(
      (): SQL =>
        sql`${budgetLines.monthly}[1] + ${budgetLines.monthly}[2] + ${budgetLines.monthly}[3] + ${budgetLines.monthly}[4] + ${budgetLines.monthly}[5] + ${budgetLines.monthly}[6] + ${budgetLines.monthly}[7] + ${budgetLines.monthly}[8] + ${budgetLines.monthly}[9] + ${budgetLines.monthly}[10] + ${budgetLines.monthly}[11] + ${budgetLines.monthly}[12]`,
    ),
    note: text(),
  },
  (t) => [
    check('budget_lines_monthly_twelve', sql`cardinality(${t.monthly}) = 12`),
    uniqueIndex('budget_lines_budget_account_cost_center_uq')
      .on(
        t.budgetId,
        t.accountId,
        sql`coalesce(${t.costCenterId}, '00000000-0000-0000-0000-000000000000'::uuid)`,
      )
      .where(live(t)),
  ],
);

