export const vendorBills = defineTable(
  'vendor_bills',
  { module: 'M24', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    /** the vendor's own invoice number */
    billNo: text().notNull(),
    vendorId: uuid()
      .references((): AnyPgColumn => vendors.id)
      .notNull(),
    poId: uuid().references((): AnyPgColumn => purchaseOrders.id),
    billDate: dateStr().notNull(),
    dueDate: dateStr().notNull(),
    subtotal: paisa().notNull(),
    tax: paisa().notNull().default(0),
    total: paisa().notNull(),
    paid: paisa().notNull().default(0),
    /** generated: `total - paid` */
    balance: paisa().generatedAlwaysAs((): SQL => sql`${vendorBills.total} - ${vendorBills.paid}`),
    status: enumText(vendorBillStatuses).notNull().default('draft'),
    approvalRequestId: uuid().references((): AnyPgColumn => approvalRequests.id),
    /** the scanned bill */
    fileId: uuid().references((): AnyPgColumn => files.id),
  },
  (t) => [
    nonNegative('vendor_bills', t.subtotal),
    nonNegative('vendor_bills', t.tax),
    nonNegative('vendor_bills', t.total),
    nonNegative('vendor_bills', t.paid),
    uniqueIndex('vendor_bills_vendor_bill_no_uq')
      .on(t.orgId, t.vendorId, t.billNo)
      .where(sql`${t.deletedAt} is null and ${t.status} <> 'void'`),
  ],
);

